/**
 * Cloudflare Worker entry: the OpenNext-built Next.js app plus the two daily
 * jobs that vercel.json runs as Vercel Cron on Vercel.
 */
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as nextHandler } from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string } & Record<string, unknown>;
type Ctx = { waitUntil(promise: Promise<unknown>): void };

const CRON_ROUTES: Record<string, string> = {
  // 03:00 UTC: copy paid orders into Odoo.
  "0 3 * * *": "/api/cron/odoo-orders",
  // 05:00 UTC (07:00 Windhoek): email staff the late / due-today orders.
  "0 5 * * *": "/api/cron/order-watchdog",
};

export default {
  fetch: nextHandler.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    const path = CRON_ROUTES[event.cron];
    if (!path || !env.CRON_SECRET) return;
    const request = new Request(`https://www.rappisportshub.com${path}`, {
      method: "GET",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(nextHandler.fetch(request, env, ctx));
  },
};

// Durable Object used by the OpenNext revalidation queue.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from "../.open-next/worker.js";
